{
  "apiVersion": 1,
  "type": "component.detail",
  "package": "@astryxdesign/core",
  "data": {
    "name": "AppShell",
    "displayName": "App Shell",
    "group": "AppShell",
    "category": "Layout",
    "keywords": [
      "appshell",
      "layout",
      "scaffold",
      "sidebar",
      "sidenav",
      "topnav",
      "header",
      "navigation",
      "dashboard",
      "shell",
      "page",
      "frame"
    ],
    "usage": {
      "description": "AppShell is the page shell for an application. It provides slots for top navigation, side navigation, banners, and main content. Use it as the root wrapper for every page. It handles responsive mobile navigation and skip-to-content automatically. Configure side nav collapse on SideNav with its collapsible prop.",
      "bestPractices": [
        {
          "guidance": true,
          "description": "Choose the right height: use \"fill\" for dashboards with internal scrolling and \"auto\" for pages that grow with content."
        },
        {
          "guidance": true,
          "description": "Set `contentPadding` based on content type: 4 for forms and settings, 0 for tables and dashboards."
        },
        {
          "guidance": true,
          "description": "Give every nav slot an accessible name. AppShell renders TopNav and SideNav as separate navigation landmarks, and a screen reader lists them by name, so pass `label` to each one."
        },
        {
          "guidance": true,
          "description": "Start the page heading inside `children`. AppShell owns the skip link, the banner landmark and the main landmark, but it renders no heading, so the first heading in the content area is the page h1."
        },
        {
          "guidance": true,
          "description": "On phones, opt the page into the full screen with `viewport-fit=cover` in the viewport meta tag (`width=device-width, initial-scale=1, viewport-fit=cover`). AppShell then extends its header under the status bar and out to the screen sides, and keeps the header's items and the end of the content inside the device's safe area. An installed web app can also draw under the status bar with `<meta name=\"apple-mobile-web-app-status-bar-style\" content=\"black-translucent\">`. In landscape only the header is inset: an inline SideNav and the content's sides still reach under a notch, so keep content padding there. A shell with no header region or phone top bar keeps no top inset; keep top padding there."
        },
        {
          "guidance": false,
          "description": "Nest one AppShell inside another; it's the outermost layout frame."
        },
        {
          "guidance": false,
          "description": "Use for sub-page layouts; use Layout for content areas within AppShell."
        },
        {
          "guidance": false,
          "description": "Add your own skip link or <main> element. AppShell already renders both, and a second main landmark makes the first ambiguous."
        }
      ],
      "anatomy": [
        {
          "name": "Page shell",
          "required": true,
          "description": "Outermost application frame that owns page-level navigation, responsive shell behavior, and the main content landmark."
        },
        {
          "name": "Skip link",
          "required": true,
          "description": "First focusable element on the page. Visually hidden until focused, then moves focus to the main content area."
        },
        {
          "name": "Banner",
          "required": false,
          "description": "The banner slot, for system-wide announcements. Renders above the top nav, inside the banner landmark."
        },
        {
          "name": "Top navigation",
          "required": false,
          "description": "The topNav slot, typically TopNav. Below the mobile breakpoint it becomes a compact bar carrying the nav toggle."
        },
        {
          "name": "Side navigation",
          "required": false,
          "description": "The sideNav slot, typically SideNav. Inline above the breakpoint, moved into the mobile drawer below it."
        },
        {
          "name": "Main content",
          "required": true,
          "description": "children, rendered in the main landmark. Scrolls internally when height is fill, and with the page when it is auto. While it scrolls content that overflows, it is a stop in the tab order; Tab entry moves on when its first focusable element is a plain link or button, and otherwise main is one stop before it."
        },
        {
          "name": "Mobile nav drawer",
          "required": false,
          "description": "Generated below the breakpoint from the nav slots unless mobileNav disables or replaces it. A modal dialog: it traps focus and returns focus to the toggle on close."
        }
      ]
    },
    "props": [
      {
        "name": "children",
        "type": "ReactNode",
        "description": "Main content area, rendered inside a <main> element."
      },
      {
        "name": "contentPadding",
        "type": "0 | 0.5 | 1 | 1.5 | 2 | 3 | 4 | 5 | 6 | 8 | 10",
        "description": "Padding for the main content area. Set based on the dominant content pattern: 4 (16px) for forms/settings/text, 0 for dashboards/maps/tables. Override individual sections with Section.",
        "default": "0"
      },
      {
        "name": "topNav",
        "type": "ReactNode",
        "description": "Top navigation slot, typically TopNav.",
        "slotElements": [
          {
            "__element": "TopNav",
            "props": {
              "label": "Navigation"
            }
          }
        ]
      },
      {
        "name": "sideNav",
        "type": "ReactNode",
        "description": "Side navigation slot, typically SideNav.",
        "slotElements": [
          {
            "__element": "SideNav",
            "props": {}
          }
        ]
      },
      {
        "name": "mobileNav",
        "type": "ReactNode",
        "description": "Mobile navigation configuration. Accepts false (disable), a config object (tune auto behavior), or ReactNode (full custom drawer). The config object is {hasToggle?: boolean, isOpen?: boolean, onOpenChange?: (isOpen: boolean) => void, content?: ReactNode, breakpoint?: 'sm' | 'md' | 'lg' | 'xl' | '2xl' | 'none', defaultIsMobile?: boolean}; breakpoint defaults to 'md', resolves through the nearest Theme's widthBreakpoints, and switches to the wider layout at equality. 'none' is always non-mobile and ignores defaultIsMobile.",
        "slotElements": [
          {
            "__element": "MobileNav",
            "props": {}
          }
        ]
      },
      {
        "name": "banner",
        "type": "ReactNode",
        "description": "Banner slot for system-wide announcements, placed above the topNav.",
        "slotElements": [
          {
            "__element": "Banner",
            "props": {
              "title": "Info",
              "status": "info",
              "container": "section"
            }
          }
        ]
      },
      {
        "name": "height",
        "type": "'fill' | 'auto'",
        "description": "Height behavior: 'fill' makes the shell fill the viewport (100dvh) with independent scroll containers; 'auto' lets the shell grow with content and uses sticky positioning for nav.",
        "default": "'fill'"
      },
      {
        "name": "variant",
        "type": "'wash' | 'surface' | 'section' | 'elevated'",
        "description": "Navigation background style controlling how nav areas contrast with content. 'wash' uses wash background, 'surface' uses surface background, 'section' adds dividers between nav and content, 'elevated' uses wash nav with elevated surface content and border radius.",
        "default": "'elevated'"
      },
      {
        "name": "xstyle",
        "type": "StyleXStyles",
        "description": "StyleX styles for layout customization (margins, positioning, sizing). Must be a stylex.create() value, not an inline style object like style={{}}."
      }
    ],
    "playground": {
      "defaults": {
        "variant": "surface",
        "contentPadding": 4,
        "topNav": {
          "__element": "TopNav",
          "props": {
            "label": "Navigation",
            "heading": {
              "__element": "TopNavHeading",
              "props": {
                "heading": "My App"
              }
            }
          }
        },
        "sideNav": {
          "__element": "SideNav",
          "props": {},
          "children": [
            {
              "__element": "SideNavItem",
              "props": {
                "label": "Dashboard",
                "isSelected": true
              }
            },
            {
              "__element": "SideNavItem",
              "props": {
                "label": "Settings"
              }
            },
            {
              "__element": "SideNavItem",
              "props": {
                "label": "Help"
              }
            }
          ]
        },
        "children": {
          "__element": "VStack",
          "props": {
            "gap": 3
          },
          "children": [
            {
              "__element": "Heading",
              "props": {
                "level": 2
              },
              "children": "Dashboard"
            },
            {
              "__element": "Text",
              "props": {
                "type": "body",
                "color": "secondary"
              },
              "children": "Welcome back. Here is an overview of your workspace."
            }
          ]
        }
      }
    },
    "theming": {
      "targets": [
        {
          "className": "astryx-app-shell",
          "visualProps": [
            "variant"
          ]
        },
        {
          "className": "astryx-app-shell-header",
          "visualProps": [
            "variant"
          ]
        },
        {
          "className": "astryx-app-shell-sidenav",
          "visualProps": [
            "variant"
          ]
        }
      ]
    },
    "package": "@astryxdesign/core",
    "import": "@astryxdesign/core/AppShell",
    "sourceAvailable": true
  },
  "meta": {
    "answeredBy": {
